package cli

import (
	"cmp"
	"io"
	"io/fs"
	"path/filepath"
	"slices"
	"strings"
	"text/tabwriter"

	"github.com/spf13/cobra"

	"github.com/antonL95/promptstor/internal/adapter"
	"github.com/antonL95/promptstor/internal/library"
	"github.com/antonL95/promptstor/internal/paths"
)

const (
	docsHome    = "/promptstor-docs/home"
	docsProject = "/promptstor-docs/project"
	envExample  = "NAME"

	adapterDocsIntro = "# Adapters\n\n" +
		"Generated by `promptstor adapters --markdown`. Do not edit this file by hand.\n\n" +
		"Paths are the defaults, with no environment variable moving them. `CODEX_HOME`, `OPENCODE_CONFIG_DIR` and `XDG_CONFIG_HOME` change where some tools are looked for. " +
		"`~` is your home folder. Project paths are relative to the repository.\n\n" +
		"A capability marked `yes` can still have limits for a particular item. PromptStor reports whatever a tool cannot express.\n\n"
	noDetection = "Detected by: nothing. PromptStor adds it to a project when a selected tool needs it.\n\n"
)

type detectLocator interface {
	DetectPaths(env paths.Env) []string
}

type adapterFacts struct {
	id             adapter.ToolID
	caps           adapter.Capabilities
	detectPaths    []string
	binaries       []string
	user, projects []string
}

var documentedKinds = []struct {
	kind  library.Kind
	label string
}{
	{library.KindRule, "rules"},
	{library.KindSkill, "skills"},
	{library.KindCommand, "commands"},
	{library.KindSubagent, "subagents"},
	{library.KindPermission, "permissions"},
	{library.KindHook, "hooks"},
	{library.KindMCP, "mcp"},
}

var capabilityRows = []struct {
	label string
	value func(adapter.Capabilities) string
}{
	{"File scoped rules", func(c adapter.Capabilities) string { return yesOrNo(c.FileScope) }},
	{"Rule activations", activationNames},
	{"Portable `deny_commands`", func(c adapter.Capabilities) string { return yesOrNo(c.Portable.DenyCommands) }},
	{"Portable `deny_paths`", func(c adapter.Capabilities) string { return yesOrNo(c.Portable.DenyPaths) }},
	{"Portable `allow_mcp_servers`", func(c adapter.Capabilities) string { return yesOrNo(c.Portable.AllowMCPServers) }},
	{"Reads a project `AGENTS.md`", func(c adapter.Capabilities) string { return yesOrNo(c.ReadsProjectAgentsMD) }},
	{"Commands written as skills", func(c adapter.Capabilities) string { return yesOrNo(c.CommandsAsSkills) }},
	{"Environment reference", envReference},
}

func newAdaptersCommand() *cobra.Command {
	var markdown bool
	cmd := &cobra.Command{
		Use:   "adapters",
		Short: "List the supported tools and what each one can express",
		Args:  cobra.NoArgs,
		RunE: func(cmd *cobra.Command, _ []string) error {
			facts := collectAdapterFacts()
			if markdown {
				return writeAdapterDocs(cmd.OutOrStdout(), facts)
			}
			return writeAdapterTable(cmd.OutOrStdout(), facts)
		},
	}
	cmd.Flags().BoolVar(&markdown, "markdown", false, "print the full reference as Markdown")
	return cmd
}

func collectAdapterFacts() []adapterFacts {
	var facts []adapterFacts
	for _, a := range adapter.All() {
		f := adapterFacts{id: a.ID(), caps: a.Capabilities()}
		env := docsEnv(&f.binaries)
		a.Detect(env)
		if locator, ok := a.(detectLocator); ok {
			for _, path := range locator.DetectPaths(env) {
				f.detectPaths = append(f.detectPaths, shortPath(path))
			}
		}
		quiet := docsEnv(new([]string))
		f.user = backupPaths(a, adapter.Target{Env: quiet, Scope: adapter.ScopeUser})
		f.projects = backupPaths(a, adapter.Target{Env: quiet, Scope: adapter.ScopeProject, ProjectRoot: docsProject})
		facts = append(facts, f)
	}
	return facts
}

func docsEnv(lookedUp *[]string) paths.Env {
	return paths.Env{
		Home:   docsHome,
		OS:     "linux",
		Getenv: func(string) string { return "" },
		LookPath: func(name string) (string, error) {
			*lookedUp = append(*lookedUp, name)
			return "", fs.ErrNotExist
		},
	}.WithBaseDirs()
}

func backupPaths(a adapter.Adapter, t adapter.Target) []string {
	var listed []string
	for _, entry := range a.BackupSet(t) {
		line := "`" + shortPath(entry.Path) + "`"
		if len(entry.Keys) > 0 {
			line += " (only `" + strings.Join(entry.Keys, "`, `") + "`)"
		}
		listed = append(listed, line)
	}
	slices.Sort(listed)
	return listed
}

func shortPath(path string) string {
	path = filepath.ToSlash(path)
	if rest, ok := strings.CutPrefix(path, docsProject+"/"); ok {
		return rest
	}
	if rest, ok := strings.CutPrefix(path, docsHome+"/"); ok {
		return "~/" + rest
	}
	return path
}

func yesOrNo(value bool) string {
	if value {
		return "yes"
	}
	return "no"
}

func activationNames(c adapter.Capabilities) string {
	var names []string
	for _, activation := range []library.Activation{library.ActivationAlways, library.ActivationFiles, library.ActivationAgent} {
		if c.Activations[activation] {
			names = append(names, string(activation))
		}
	}
	return cmp.Or(strings.Join(names, ", "), "none declared")
}

func envReference(c adapter.Capabilities) string {
	if c.EnvRef == nil {
		return "none"
	}
	return "`" + c.EnvRef(envExample) + "`"
}

func writeAdapterTable(out io.Writer, facts []adapterFacts) error {
	table := tabwriter.NewWriter(out, 0, 0, 2, ' ', 0)
	w := &printer{w: table}
	w.printf("TOOL\tKINDS\tUSER SKILLS\n")
	for _, f := range facts {
		var kinds []string
		for _, documented := range documentedKinds {
			if f.caps.Kinds[documented.kind] {
				kinds = append(kinds, documented.label)
			}
		}
		skills := cmp.Or(strings.Join(f.caps.SkillHomes[adapter.ScopeUser], ", "), "none")
		w.printf("%s\t%s\t%s\n", f.id, strings.Join(kinds, ", "), skills)
	}
	if w.err == nil {
		w.err = table.Flush()
	}
	return w.done()
}

func writeAdapterDocs(out io.Writer, facts []adapterFacts) error {
	w := &printer{w: out}
	w.printf("%s", adapterDocsIntro)
	writeCapabilityTable(w, facts)
	for _, f := range facts {
		writeAdapterSection(w, f)
	}
	return w.done()
}

func writeCapabilityTable(w *printer, facts []adapterFacts) {
	row := func(label string, cell func(adapterFacts) string) {
		w.printf("| %s |", label)
		for _, f := range facts {
			w.printf(" %s |", cell(f))
		}
		w.printf("\n")
	}
	w.printf("## Capabilities\n\n")
	row("Capability", func(f adapterFacts) string { return f.id })
	w.printf("|%s\n", strings.Repeat("---|", len(facts)+1))
	for _, documented := range documentedKinds {
		row("Kind: "+documented.label, func(f adapterFacts) string { return yesOrNo(f.caps.Kinds[documented.kind]) })
	}
	for _, capability := range capabilityRows {
		row(capability.label, func(f adapterFacts) string { return capability.value(f.caps) })
	}
}

func writeAdapterSection(w *printer, f adapterFacts) {
	w.printf("\n## %s\n\n", f.id)
	writeDetection(w, f)
	writeSkillHomes(w, f)
	writeFileList(w, "User files in the first run backup", f.user)
	writeFileList(w, "Project files in the first run backup", f.projects)
}

func writeDetection(w *printer, f adapterFacts) {
	var signs []string
	for _, path := range f.detectPaths {
		signs = append(signs, "`"+path+"`")
	}
	for _, name := range f.binaries {
		signs = append(signs, "`"+name+"` on the PATH")
	}
	if len(signs) == 0 {
		w.printf("%s", noDetection)
		return
	}
	w.printf("Detected by any of: %s.\n\n", strings.Join(signs, ", "))
}

func writeSkillHomes(w *printer, f adapterFacts) {
	user := f.caps.SkillHomes[adapter.ScopeUser]
	project := f.caps.SkillHomes[adapter.ScopeProject]
	if len(user)+len(project) == 0 {
		w.printf("Skill homes: none.\n")
		return
	}
	w.printf("Skill homes: `%s` (user), `%s` (project).\n", strings.Join(user, "`, `"), strings.Join(project, "`, `"))
}

func writeFileList(w *printer, title string, files []string) {
	if len(files) == 0 {
		return
	}
	w.printf("\n%s:\n\n", title)
	for _, file := range files {
		w.printf("- %s\n", file)
	}
}
